-- Scenario fixture for the Clicky addon: clicks, hovers and types, then notes the addon's event log.
return {
  run = function(s)
    s:login()
    s:click("ClickyButton")
    s:click("ClickyCheck")
    s:enter("ClickyButton")
    s:enter("ClickyCheck")
    s:unit("mouseover", { name = "Bob" })
    s:hover("mouseover")
    s:type("ClickyBox", "hi")
    s:press("ClickyBox", "ENTER")
    -- UIDropDownMenu menu (Task 3.6)
    s:click("ClickyMenuButton")
    s:snapshot("dropdown_menu", s:menu())
    s:enter(s:menu().levels[1].entries[8].frame)
    s:snapshot("dropdown_submenu", s:menu())
    s:pick({ "More", "Nested" })
    s:closeMenus()
    -- Menu API (Task 4.5)
    s:closeMenus()
    s:click("ClickyMenuApiButton", "RightButton")
    s:snapshot("menu_api", s:menu())
    s:enter(s:menu().levels[1].entries[3].frame) -- "More"
    s:snapshot("menu_api_submenu", s:menu())
    s:pick({ "More", "Deep" })
    assert(s:menu() == nil, "a leaf pick closes the menu")
    assert(s.ns.menuApi.picks[1] == "Deep", "Deep callback ran")
    s:click("ClickyMenuApiButton", "RightButton")
    s:pick("Check")
    s:snapshot("menu_api_checked", s:menu())
    s:closeMenus()
    s:openMenu("FRIEND", { clicky = true })
    s:snapshot("menu_unit", s:menu())
    s:closeMenus()
    s:note("log: " .. table.concat(s.ns.log, ";"))
  end,
}
